CREATE TABLE ibexa_content_bookmark (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, node_id INTEGER DEFAULT 0 NOT NULL, user_id INTEGER DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT '' NOT NULL, CONSTRAINT ibexa_content_bookmark_location_fk FOREIGN KEY (node_id) REFERENCES ibexa_content_tree (node_id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT ibexa_content_bookmark_user_fk FOREIGN KEY (user_id) REFERENCES ibexa_user (contentobject_id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
